{
  "title": "迷雾之谷",
  "scene": "你站在一片浓雾缭绕的山谷中，四周回荡着奇异的鸟鸣声。山谷中央有一座石碑，碑上刻着一首古文，隐约可见模糊的字迹。你向前方的两个方向望去，一个方向隐约可见一条小溪流过，另一个方向则是一片茂密的树林。",
  "goal": "找到通往山海秘境的入口。",
  "clue": "石碑上的古文含有线索。",
  "choices": [
    {"id": "A", "text": "去小溪边寻找线索", "outcome": "小溪边找到一张古老的地图碎片，但地图上其他标记模糊不清。", "result": "partial", "next": "retry"},
    {"id": "B", "text": "穿过树林探索", "outcome": "树林里发现一些奇异的脚印，但没有找到任何有用的物品。", "result": "retry", "next": "retry"},
    {"id": "C", "text": "仔细阅读石碑上的古文", "outcome": "石碑上的古文揭示了‘雾中有秘境’的秘密，指引你前往迷雾中心找寻真正的入口。", "result": "success", "next": "next_level"}
  ]
}
